{
  "errors": [
    {
      "error": "Unsupported keyword 'maxItems' at path: properties.events"
    },
    {
      "error": "Unsupported keyword 'maxItems' at path: properties.vendor_directory"
    },
    {
      "error": "Unsupported keyword 'maxItems' at path: properties.vendor_roster"
    },
    {
      "error": "Unsupported keyword 'maxItems' at path: properties.programs"
    }
  ],
  "output_schema": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "identity_match": {
        "type": "string",
        "enum": [
          "exact_market",
          "could_not_verify"
        ],
        "description": "Only exact market identity AND locality supported by published official excerpts. Matching street name or generic operator is insufficient. Could_not_verify if wrong town, shared roster, stale evidence, or ambiguous name."
      },
      "identity_evidence": {
        "type": "string",
        "description": "Verbatim official excerpt identifying the exact market name and city/locality (plus state/province or address when published). Cite the input official host."
      },
      "events": {
        "type": "array",
        "maxItems": 6,
        "description": "Up to 6 future/current one-off events explicitly assigned to this market, exact published YEAR required. Not regular weekly dates, expired events, or unrelated operator events. Empty when unsupported.",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "name": {
              "type": "string",
              "description": "Exact published event name"
            },
            "kind": {
              "type": "string",
              "enum": [
                "music",
                "workshop",
                "kids",
                "festival",
                "special_market",
                "other"
              ]
            },
            "start_date": {
              "type": "string",
              "description": "YYYY-MM-DD; explicit published year required, on/after research date"
            },
            "end_date": {
              "type": "string",
              "description": "YYYY-MM-DD if explicitly published; otherwise empty"
            },
            "published_hours": {
              "type": "string",
              "description": "Exact published local hours text, otherwise empty; never infer timezone"
            },
            "venue": {
              "type": "string",
              "description": "Exact published venue for this event, otherwise empty"
            },
            "source_url": {
              "type": "string",
              "description": "Exact primary official page URL publishing THIS item for THIS market. Use the input official host. Never a generic all-markets roster, directory, social post, or another locality."
            },
            "evidence_excerpt": {
              "type": "string",
              "description": "Verbatim source excerpt containing the item name, market assignment, and explicit date/year or roster period. Include this same excerpt in API basis citations. Never paraphrase or infer the year."
            }
          },
          "required": [
            "name",
            "kind",
            "start_date",
            "end_date",
            "published_hours",
            "venue",
            "source_url",
            "evidence_excerpt"
          ]
        }
      },
      "vendor_directory": {
        "type": "array",
        "maxItems": 1,
        "description": "One current official MARKET-SPECIFIC seller/weekly roster link. Generic multi-market seller directory is not enough. Empty when unsupported.",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "url": {
              "type": "string",
              "description": "Exact market-specific official directory/roster URL on input host"
            },
            "kind": {
              "type": "string",
              "enum": [
                "directory",
                "weekly_roster"
              ]
            },
            "source_url": {
              "type": "string",
              "description": "Exact primary official page URL publishing THIS item for THIS market. Use the input official host. Never a generic all-markets roster, directory, social post, or another locality."
            },
            "evidence_excerpt": {
              "type": "string",
              "description": "Verbatim source excerpt containing the item name, market assignment, and explicit date/year or roster period. Include this same excerpt in API basis citations. Never paraphrase or infer the year."
            }
          },
          "required": [
            "url",
            "kind",
            "source_url",
            "evidence_excerpt"
          ]
        }
      },
      "vendor_roster": {
        "type": "array",
        "maxItems": 12,
        "description": "Up to 12 named vendors explicitly assigned to THIS market in a dated currently applicable official roster. Non-exhaustive. No attendance claim; reject lists whose season ended before research_date, undated rosters, generic all-market vendors, sponsors, applicants, and operator employees.",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "name": {
              "type": "string",
              "description": "Exact published vendor name"
            },
            "period": {
              "type": "string",
              "description": "Exact published current roster period, including year"
            },
            "start_date": {
              "type": "string",
              "description": "YYYY-MM-DD when explicitly published, otherwise empty"
            },
            "end_date": {
              "type": "string",
              "description": "YYYY-MM-DD when explicitly published, otherwise empty"
            },
            "source_url": {
              "type": "string",
              "description": "Exact primary official page URL publishing THIS item for THIS market. Use the input official host. Never a generic all-markets roster, directory, social post, or another locality."
            },
            "evidence_excerpt": {
              "type": "string",
              "description": "Verbatim source excerpt containing the item name, market assignment, and explicit date/year or roster period. Include this same excerpt in API basis citations. Never paraphrase or infer the year."
            }
          },
          "required": [
            "name",
            "period",
            "start_date",
            "end_date",
            "source_url",
            "evidence_excerpt"
          ]
        }
      },
      "programs": {
        "type": "array",
        "maxItems": 4,
        "description": "Current market-specific named recurring visitor programs with official explicit current-year evidence. No guesses from generic benefit policies or prior-year announcements.",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "name": {
              "type": "string",
              "description": "Exact named program"
            },
            "kind": {
              "type": "string",
              "enum": [
                "nutrition",
                "kids_club",
                "food_access",
                "composting",
                "community",
                "education",
                "other"
              ]
            },
            "year": {
              "type": "string",
              "description": "Explicit current published year, e.g. 2026"
            },
            "description": {
              "type": "string",
              "description": "One short verbatim published description"
            },
            "source_url": {
              "type": "string",
              "description": "Exact primary official page URL publishing THIS item for THIS market. Use the input official host. Never a generic all-markets roster, directory, social post, or another locality."
            },
            "evidence_excerpt": {
              "type": "string",
              "description": "Verbatim source excerpt containing the item name, market assignment, and explicit date/year or roster period. Include this same excerpt in API basis citations. Never paraphrase or infer the year."
            }
          },
          "required": [
            "name",
            "kind",
            "year",
            "description",
            "source_url",
            "evidence_excerpt"
          ]
        }
      }
    },
    "required": [
      "identity_match",
      "identity_evidence",
      "events",
      "vendor_directory",
      "vendor_roster",
      "programs"
    ]
  },
  "documentation_url": "https://docs.parallel.ai/task-api/guides/specify-a-task"
}
